//go:build integration

package bot

import (
	"context"
	"database/sql"
	"errors"
	"path/filepath"
	"runtime"
	"testing"

	"github.com/jackc/pgx/v5"
	"github.com/openclaw/clawguard/internal/store"
	"github.com/pressly/goose/v3"
)

func TestVerificationCleanupSettlementMigrationPreservesRecovery(t *testing.T) {
	ctx := context.Background()
	pool, q, s, transport := settlementFixture(t)

	// Both outcomes are generated by the actual handler and mocked Telegram.
	settled := settlementPending(t, q, 201, "button", `{}`)
	if _, err := s.HandleVerificationExpiry(ctx, settled); err != nil {
		t.Fatalf("settle initial cleanup: %v", err)
	}
	pending := settlementPending(t, q, 202, "button", `{}`)
	settlementTrigger(t, pool, "violations", true)
	if _, err := s.HandleVerificationExpiry(ctx, pending); err == nil {
		t.Fatal("expected injected violation insert failure")
	}
	settlementTrigger(t, pool, "violations", false)
	calls := countString(transport.Methods(), "kickChatMember")
	if calls != 2 {
		t.Fatalf("expected two initial Telegram actions, got %d", calls)
	}
	var total, done int
	if err := pool.QueryRow(ctx, `SELECT count(*),count(*) FILTER (WHERE settled) FROM verification_cleanup_settlements`).Scan(&total, &done); err != nil || total != 2 || done != 1 {
		t.Fatalf("expected one settled and one pending result: total=%d done=%d err=%v", total, done, err)
	}
	snapshot := func() string {
		t.Helper()
		var result string
		if err := pool.QueryRow(ctx, `SELECT jsonb_agg(to_jsonb(s) ORDER BY operation_key)::text FROM verification_cleanup_settlements s`).Scan(&result); err != nil {
			t.Fatal(err)
		}
		return result
	}
	before := snapshot()

	db, err := sql.Open("pgx", pool.Config().ConnString())
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	db.SetMaxOpenConns(1)
	_, file, _, ok := runtime.Caller(0)
	if !ok {
		t.Fatal("runtime.Caller failed")
	}
	dir := filepath.Join(filepath.Dir(file), "..", "..", "migrations")
	if err := goose.DownContext(ctx, db, dir); err != nil {
		t.Fatalf("goose rollback: %v", err)
	}
	// Other packages may supply migrations 042–045 before integration.
	if version, err := goose.GetDBVersionContext(ctx, db); err != nil || version <= 0 || version >= 46 {
		t.Fatalf("rollback version=%d err=%v", version, err)
	}
	if got := snapshot(); got != before {
		t.Fatalf("rollback changed settlement records: before=%s after=%s", before, got)
	}
	if err := goose.UpContext(ctx, db, dir); err != nil {
		t.Fatalf("goose re-upgrade: %v", err)
	}
	if version, err := goose.GetDBVersionContext(ctx, db); err != nil || version != 46 {
		t.Fatalf("re-upgrade version=%d err=%v", version, err)
	}
	if got := snapshot(); got != before {
		t.Fatalf("re-upgrade changed settlement records: before=%s after=%s", before, got)
	}
	var indexExists bool
	if err := pool.QueryRow(ctx, `SELECT to_regclass('verification_cleanup_unsettled_idx') IS NOT NULL`).Scan(&indexExists); err != nil || !indexExists {
		t.Fatalf("settlement index missing after re-upgrade: %v %v", indexExists, err)
	}

	// Retrying either result after the migration must not call Telegram again;
	// the old incomplete result is logged once and the pending instance removed.
	for _, item := range []store.PendingVerification{settled, pending, pending} {
		if _, err := s.HandleVerificationExpiry(ctx, item); err != nil {
			t.Fatalf("retry after migration: %v", err)
		}
	}
	if got := countString(transport.Methods(), "kickChatMember"); got != calls {
		t.Fatalf("Telegram action repeated: before=%d after=%d", calls, got)
	}
	if a, b := cleanupCount(t, pool, 201), cleanupCount(t, pool, 202); a != 1 || b != 1 {
		t.Fatalf("expected one violation each: %d %d", a, b)
	}
	if _, err := q.GetPendingVerification(ctx, store.GetPendingVerificationParams{ChatID: -90001, UserID: 202}); !errors.Is(err, pgx.ErrNoRows) {
		t.Fatalf("completed pending verification still present or query failed: %v", err)
	}
}
